<section dir={$pageDirection}>
	<div class="container mx-auto px-5 2xl:px-0">
		<!-- intro paragraph -->
		<div class="py-8 lg:py-12">
			<p class="text-xl lg:text-3xl font-light text-primary-400-500-token max-lg:text-center">
				{$LL.newSubscription.formIntro()}
			</p>
		</div>
		<!-- form -->
		<form method="POST" use:enhance>
			<div class="grid lg:grid-cols-2 gap-4 lg:gap-x-16 lg:gap-y-8 pb-12 lg:pb-24">
				<!-- level selection -->
				<div class="lg:col-span-2 pb-3">
					<p class="text-xl pb-5">{$LL.newSubscription.form.selectMSG()}</p>
					<div class="grid sm:grid-cols-3 text-xl font-light max-lg:space-y-3">
						<label class="flex items-center space-x-2">
							<input
								class="radio"
								required
								type="radio"
								name="level"
								value="Silver"
								bind:group={$form.level}
							/>
							<p class="px-2">{$LL.newSubscription.form.silver()}</p>
						</label>
						<label class="flex items-center space-x-2">
							<input
								class="radio"
								required
								type="radio"
								name="level"
								value="Gold"
								bind:group={$form.level}
							/>
							<p class="px-2">{$LL.newSubscription.form.gold()}</p>
						</label>
						<label class="flex items-center space-x-2">
							<input
								class="radio"
								required
								type="radio"
								name="level"
								value="Diamond"
								bind:group={$form.level}
							/>
							<p class="px-2">{$LL.newSubscription.form.diamond()}</p>
						</label>
					</div>
				</div>

				<!-- name -->
				<div class="m-0 p-0">
					<label class="label">
						<div class="text-lg">
							<span>{$LL.newSubscription.form.fullName()}</span>
						</div>

						<input
							bind:value={$form.name}
							class="input text-lg text-surface-900-50-token bg-surface-50-900-token rounded-lg focus:border-surface-700-200-token"
							type="text"
							name="name"
							{...$constraints.name}
							placeholder={$LL.newSubscription.form.fullNamePlaceholder()}
						/>
					</label>
					{#if $errors.name}<span class="text-warning-600">{$errors.name}</span>{/if}
				</div>

				<!-- company -->
				<div class="m-0 p-0">
					<label class="label">
						<div class="text-lg">
							<span>{$LL.newSubscription.form.companyName()}</span>
						</div>

						<input
							bind:value={$form.companyName}
							class="input text-lg text-surface-900-50-token bg-surface-50-900-token rounded-lg focus:border-surface-700-200-token"
							type="text"
							name="companyName"
							{...$constraints.companyName}
							placeholder={$LL.newSubscription.form.companyNamePlaceholder()}
						/>
					</label>
					{#if $errors.companyName}<span class="text-warning-600">{$errors.companyName}</span>{/if}
				</div>

				<!-- mobile number -->
				<div>
					<div class="m-0 p-0">
						<label class="label">
							<div class="text-lg">
								<span>{$LL.newSubscription.form.mobileNumber()}</span>
							</div>
							<input
								bind:value={$form.mobileNumber}
								class="input text-lg text-surface-900-50-token bg-surface-50-900-token rounded-lg focus:border-surface-700-200-token"
								type="tel"
								title="Input (number)"
								name="mobileNumber"
								placeholder={$LL.newSubscription.form.mobileNumberPlaceholder()}
								{...$constraints.mobileNumber}
							/>
						</label>
						{#if $errors.mobileNumber}<span class="text-warning-600">{$errors.mobileNumber}</span
							>{/if}
					</div>
				</div>

				<!-- email -->
				<div>
					<div class="m-0 p-0">
						<label class="label">
							<div class="text-lg">
								<span>{$LL.newSubscription.form.email()}</span>
							</div>
							<input
								type="email"
								name="email"
								autocomplete="email"
								{...$constraints.email}
								bind:value={$form.email}
								class="input text-lg text-surface-900-50-token bg-surface-50-900-token rounded-lg focus:border-surface-700-200-token"
								placeholder={$LL.newSubscription.form.emailPlaceholder()}
							/>
						</label>

						{#if $errors.email}<span class="text-warning-600">{$errors.email}</span>{/if}
					</div>
				</div>

				<!-- textarea -->
				<div>
					<div class="m-0 p-0">
						<label class="label">
							<div class="text-lg">
								<span>{$LL.newSubscription.form.textArea()}</span>
							</div>
							<textarea
								class="input text-lg text-surface-900-50-token bg-surface-50-900-token rounded-lg focus:border-surface-700-200-token"
								rows="5"
								{...$constraints.textArea}
								placeholder={$LL.newSubscription.form.textAreaPlaceholder()}
								bind:value={$form.textArea}
								title="textarea"
								name="textArea"
							/>
						</label>
						{#if $errors.textArea}<span class="text-warning-600">{$errors.textArea}</span>{/if}
					</div>
				</div>

				<!-- submit button -->
				<div>
					<div class="h-full flex items-end lg:justify-end p-0 m-0">
						<div class=" order-last lg:order-first">
							<p class={`${appliedClass} text-lg mx-3`}>
								{formSubmitMessage}
							</p>
						</div>
						<div>
							<button
								type="submit"
								class="btn variant-ringed-surface rounded-lg px-16 py-[10px] text-lg mt-3"
							>
								<span class="px-3 mt-1"
									><svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 32 32"
										fill="#FFF"
										width="18"
										height="18"
										><g data-name="21-Email-Send"
											><path
												d="M29 4H3a3 3 0 0 0-3 3v4h2V7.23l13.42 9.58a1 1 0 0 0 1.16 0L30 7.23V25a1 1 0 0 1-1 1H4v2h25a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3zM16 14.77 3.72 6h24.56zM0 26h2v2H0z"
											/><path d="M0 21h14v2H0zM16 21h2v2h-2zM0 16h2v2H0zM4 16h6v2H4z" /></g
										></svg
									></span
								>
								<span class="mt-1">{$LL.career.submit()}</span>
							</button>
						</div>
					</div>
				</div>
			</div>
		</form>
	</div>
</section>
